<?php $page_title='Request Food'; require_once 'includes/header.php'; require_login();
$food_id=(int)($_GET['food_id']??$_POST['food_id']??0); $food=null;
if($food_id){$s=$pdo->prepare("SELECT * FROM food_donations WHERE id=? AND status='available'");$s->execute([$food_id]);$food=$s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$food_id=(int)$_POST['food_id'];$message=trim($_POST['message']??'');$qty=(int)($_POST['quantity']??0);$s=$pdo->prepare("SELECT * FROM food_donations WHERE id=? AND status='available'");$s->execute([$food_id]);$food=$s->fetch();if(!$food||$qty<1||$qty>$food['quantity']){flash('error','Invalid food item or quantity.');}else{$ins=$pdo->prepare("INSERT INTO food_requests (food_id,requester_id,quantity,message,status) VALUES (?,?,?,?, 'pending')");$ins->execute([$food_id,user()['id'],$qty,$message]);notify_user((int)$food['donor_id'],'New food request',user()['name'].' requested '.$qty.' '.$food['unit'].' of '.$food['title'].'.','dashboard.php');flash('success','Your request has been sent to the donor.');redirect('dashboard.php');}}
?>
<section class="form-page"><div class="form-intro"><span class="kicker">COMMUNITY REQUEST</span><h1>Need food?</h1><p>Choose an available donation and send a pickup request. The donor can review it from their dashboard.</p><a class="text-link" href="food.php">← Browse all food</a></div><div class="form-card"><h2>Request <?= $food ? e($food['title']) : 'food' ?></h2><?php if($food): ?><div class="selected-food"><b><?= e($food['title']) ?></b><span><?= (int)$food['quantity'] ?> <?= e($food['unit']) ?> available · <?= e($food['location']) ?></span></div><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="food_id" value="<?= (int)$food['id'] ?>"><label>Quantity *<input type="number" name="quantity" min="1" max="<?= (int)$food['quantity'] ?>" value="1" required></label><label>Message<textarea name="message" rows="5" placeholder="Tell the donor why you need the food and your preferred pickup time."></textarea></label><button class="btn primary full-btn">Send request →</button></form><?php else: ?><div class="empty-state"><h3>Select a food listing first</h3><a class="btn primary" href="food.php">Browse available food</a></div><?php endif; ?></div></section>
